    private readonly ActorDataOperations _data=new();private readonly ActorAnimationOperations _animation=new();private readonly ActorPropertyBatchOperations _batch=new();
    private static Settings Map(Control owner,string key)=>owner.Get(key).AsGodotDictionary();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private Variant Definition(Node editor,Resource actor){var definition=_definitions.get_definition(editor.Get("registry").As<RefCounted>(),actor.Get("type_id").AsStringName());return definition!=null?Variant.From(definition):default;}
    public void begin_drag(Control owner,StringName key,Vector2 position)
    {
        var runtime=selected_runtime(owner);if(runtime==null)return;owner.Set("drag_key",key);owner.Set("start_mouse",position);owner.Set("center",Anchor(runtime).Position);owner.Set("visual_transform",Anchor(runtime).Transform);var editor=Editor(owner)!;var model=Model(editor);var selected=model.Call("selected_actors").AsGodotArray();var actors=new GArray();var origins=Map(owner,"origins");var parents=Map(owner,"parents");foreach(var value in selected){var actor=value.As<Resource>();if(!actor.Get("type_id").AsString().EndsWith("_2d",StringComparison.Ordinal))continue;var ancestor=model.Call("actor_for_id",actor.Get("parent_id")).As<Resource>();bool nested=false;var visited=new HashSet<string>();while(ancestor!=null){if(!visited.Add(ancestor.Get("id").AsString())||selected.Contains(ancestor)){nested=true;break;}ancestor=model.Call("actor_for_id",ancestor.Get("parent_id")).As<Resource>();}if(nested)continue;actors.Add(actor);var sampled=_animation.sampled_values(actor,actor.Get("animation_time").AsDouble());origins[actor.Get("id")]=Get(sampled,key.ToString(),_data.get_value(actor,key,default));var current=Runtime(editor,model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>());if(IsUi(current)){var local=new Transform2D(Mathf.DegToRad(Get(sampled,"rotation",0.0).AsSingle()),Get(sampled,"scale",Vector2.One).AsVector2(),0,Get(sampled,"position",Vector2.Zero).AsVector2());parents[actor.Get("id")]=Anchor(current!).Transform*local.AffineInverse();}}owner.Set("before",_batch.capture(owner.Get("batch").As<RefCounted>(),actors,key));Map(owner,"final_values").Clear();owner.GrabFocus();editor.Get("hints").AsGodotObject().Call("begin",owner,"Esc cancels "+(key.ToString()=="size"?"resize":"transform"));
    }
    public void update_drag(Control owner,Vector2 position)
    {
        var editor=Editor(owner)!;var model=Model(editor);var start=owner.Get("start_mouse").AsVector2();var center=owner.Get("center").AsVector2();var key=owner.Get("drag_key").AsStringName();foreach(var item in owner.Get("before").AsGodotArray()){var state=item.AsGodotDictionary();var actor=state["actor"].As<Resource>();string id=actor.Get("id").AsString();var value=Get(Map(owner,"origins"),id,state["value"]);switch(key.ToString()){case "size":var delta=owner.Get("visual_transform").AsTransform2D().BasisXformInv(position-start);value=(value.AsVector2()+delta*owner.Get("resize_axis").AsVector2()*2).Max(new Vector2(16,16));break;case "position":value=value.AsVector2()+Get(Map(owner,"parents"),id,Transform2D.Identity).AsTransform2D().BasisXformInv(position-start);break;case "rotation":value=value.AsDouble()+(start.DistanceTo(center)<12?(position.X-start.X)*.5:Mathf.RadToDeg((position-center).Angle()-(start-center).Angle()));break;case "scale":value=value.AsVector2()*(float)Math.Max(.01,start.DistanceTo(center)<24?1+(position.X-start.X-position.Y+start.Y)/160:position.DistanceTo(center)/start.DistanceTo(center));break;}Map(owner,"final_values")[id]=value;model.Call("preview_property",actor,Definition(editor,actor),key,value);}
    }
    public void finish_drag(Control owner,bool cancel)
    {
        var before=owner.Get("before").AsGodotArray();if(before.Count==0)return;var editor=Editor(owner)!;var model=Model(editor);var batch=owner.Get("batch").As<RefCounted>();var key=owner.Get("drag_key").AsStringName();if(cancel)_batch.restore(batch,before);else if(Map(owner,"final_values").Count>0){var actors=new GArray();bool previous=model.Get("property_batch_active").AsBool();model.Set("property_batch_active",true);try{foreach(var item in before){var state=item.AsGodotDictionary();var actor=state["actor"].As<Resource>();actors.Add(actor);model.Call("commit_property_preview",actor,Definition(editor,actor),key,state["value"],Get(Map(owner,"final_values"),actor.Get("id").AsString(),state["value"]));}}finally{model.Set("property_batch_active",previous);}_batch.commit(batch,before,Variant.From(_batch.capture(batch,actors,key)).AsGodotArray(),key);}owner.Set("before",new Godot.Collections.Array<Settings>());Map(owner,"parents").Clear();Map(owner,"origins").Clear();Map(owner,"final_values").Clear();editor.Get("hints").AsGodotObject().Call("end",owner);
    }
    private IEnumerable<Vector2> ResizeHandles(Control owner,Node3D runtime)=>corners(owner,runtime).Concat(handle_points(owner,runtime)["edges"].AsGodotArray().Select(value=>value.AsVector2()));
    private static bool Active(Node3D? runtime)=>runtime!=null&&runtime.Get("active").AsBool();
    public void gui_input(Control owner,InputEvent input)
    {
        var editor=Editor(owner);if(!GodotObject.IsInstanceValid(editor)||editor!.Get("exporting").AsBool()||editor.Get("audio_recorder").AsGodotObject().Get("recording").AsBool()||editor.Get("screen_recorder").AsGodotObject().Get("recording").AsBool())return;
        if(owner.Get("preview_dragging").AsBool()){if(input is InputEventMouseMotion motion){owner.Set("preview_user_moved",true);owner.Set("preview_position",motion.Position-owner.Get("preview_drag_delta").AsVector2());preview_rect(owner);owner.QueueRedraw();owner.AcceptEvent();return;}if(input is InputEventMouseButton release&&release.ButtonIndex==MouseButton.Left&&!release.Pressed){owner.Set("preview_dragging",false);owner.AcceptEvent();return;}}
        if(owner.Get("preview_active").AsBool()&&input is InputEventMouseButton previewClick&&previewClick.ButtonIndex==MouseButton.Left&&preview_rect(owner).HasPoint(previewClick.Position)){if(previewClick.Pressed&&previewClick.Position.Y<owner.Get("preview_position").AsVector2().Y+24){owner.Set("preview_dragging",true);owner.Set("preview_drag_delta",previewClick.Position-owner.Get("preview_position").AsVector2());}owner.AcceptEvent();return;}
        var spatial=owner.Get("spatial").As<Node>();if(spatial.Call("handle_event",input).AsBool()){owner.AcceptEvent();return;}var before=owner.Get("before").AsGodotArray();if(input is InputEventKey key&&key.Pressed&&!key.Echo&&owner.HasFocus()&&!Input.IsMouseButtonPressed(MouseButton.Right)&&(input.IsActionPressed("undo")||input.IsActionPressed("redo"))){var rig=spatial.Get("rig").AsGodotObject();if(rig.Get("before").AsGodotDictionary().Count>0)rig.Call("finish",true);else if(spatial.Get("before").AsGodotArray().Count>0)spatial.Call("finish",true);else if(before.Count>0)finish_drag(owner,true);else editor.Call(input.IsActionPressed("redo")?"redo":"undo");owner.AcceptEvent();return;}if(input is InputEventKey escape&&escape.Pressed&&escape.Keycode==Key.Escape&&before.Count>0){finish_drag(owner,true);owner.AcceptEvent();return;}
        if(input is InputEventMouseMotion drag&&before.Count>0){update_drag(owner,scene_point(owner,drag.Position));owner.AcceptEvent();return;}if(input is InputEventMouseMotion hover){owner.TooltipText="";owner.MouseDefaultCursorShape=Control.CursorShape.Arrow;if(owner.Get("preview_active").AsBool()&&preview_rect(owner).HasPoint(hover.Position)){if(hover.Position.Y<owner.Get("preview_position").AsVector2().Y+24){owner.TooltipText="Drag to move camera preview";owner.MouseDefaultCursorShape=Control.CursorShape.Move;}return;}var selected=selected_runtime(owner);if(Active(selected)){var handles=handle_points(owner,selected!);if(handles["rotation"].AsVector2().DistanceTo(hover.Position)<16){owner.TooltipText="Rotate";owner.MouseDefaultCursorShape=Control.CursorShape.Cross;}else if(handles["scale"].AsVector2().DistanceTo(hover.Position)<16){owner.TooltipText="Scale";owner.MouseDefaultCursorShape=Control.CursorShape.Fdiagsize;}else{foreach(var point in ResizeHandles(owner,selected!))if(point.DistanceTo(hover.Position)<14){owner.TooltipText="Resize";owner.MouseDefaultCursorShape=Control.CursorShape.Fdiagsize;}if(owner.TooltipText.Length==0&&Geometry2D.IsPointInPolygon(hover.Position,corners(owner,selected!))){owner.TooltipText="Move";owner.MouseDefaultCursorShape=Control.CursorShape.Move;}}}if(selected==null)spatial.Call("hover",hover.Position);return;}
        if(input is not InputEventMouseButton click||click.ButtonIndex!=MouseButton.Left)return;if(!click.Pressed){if(before.Count>0){finish_drag(owner,false);owner.AcceptEvent();}return;}if(Input.IsMouseButtonPressed(MouseButton.Right))return;var runtime=selected_runtime(owner);if(Active(runtime)&&!click.CtrlPressed&&!click.ShiftPressed){var handles=handle_points(owner,runtime!);if(handles["rotation"].AsVector2().DistanceTo(click.Position)<16){begin_drag(owner,new StringName("rotation"),scene_point(owner,click.Position));owner.AcceptEvent();return;}if(handles["scale"].AsVector2().DistanceTo(click.Position)<16){begin_drag(owner,new StringName("scale"),scene_point(owner,click.Position));owner.AcceptEvent();return;}var axes=new[]{new Vector2(-1,-1),new Vector2(1,-1),new Vector2(1,1),new Vector2(-1,1),new Vector2(-1,0),new Vector2(1,0),new Vector2(0,-1),new Vector2(0,1)};var points=ResizeHandles(owner,runtime!).ToArray();for(int i=0;i<points.Length;i++)if(points[i].DistanceTo(click.Position)<14){owner.Set("resize_axis",axes[i]);begin_drag(owner,new StringName("size"),scene_point(owner,click.Position));owner.AcceptEvent();return;}}
        var model=Model(editor);var clips=model.Get("clips").AsGodotArray();for(int index=clips.Count-1;index>=0;index--){var clip=clips[index].As<Resource>();var candidate=Runtime(editor,clip);if(!IsUi(candidate)||!Active(candidate)||!Geometry2D.IsPointInPolygon(click.Position,corners(owner,candidate!)))continue;string id=clip.Get("id").AsString();if(click.CtrlPressed)model.Call("toggle_selection",id);else model.Call("select",id,click.ShiftPressed||model.Call("is_selected",id).AsBool());if(!click.CtrlPressed&&!click.ShiftPressed)begin_drag(owner,new StringName("position"),scene_point(owner,click.Position));owner.AcceptEvent();return;}string hit=spatial.Call("pick",click.Position).AsString();if(hit.Length>0){if(click.CtrlPressed)model.Call("toggle_selection",hit);else model.Call("select",hit,click.ShiftPressed||model.Call("is_selected",hit).AsBool());owner.GrabFocus();owner.AcceptEvent();}else if(!click.CtrlPressed&&!click.ShiftPressed&&spatial.Call("in_picture",click.Position).AsBool()){model.Call("select","",false);owner.GrabFocus();owner.AcceptEvent();}
    }
